#!/usr/bin/env bash
# Generated by: GPT-6 (Codex)
# 插件保留现有清单，Zsh 和 Vim 共用同一个 fzf 可执行文件。
set -euo pipefail
source "$(dirname -- "${BASH_SOURCE[0]}")/../../scripts/lib.sh"
module_context
clone_components vim
fzf_dir="$DOTFILES_ROOT/config/vim/.vim/bundle/fzf"
